#!/usr/bin/env bash
# Bundle item 145_edu_env_energy_nov22 (thread "Site: Add more committees and subcommittees", 22 Nov 2569; asked by
# "Site: Update automatically three times a day" at 20:12 UTC). ONE SELF-CONTAINED FILE: the payload (page changes, share
# pages/cards, calendar files) is embedded at the end of this script as base64 tar.gz, so nothing else needs copying.
# Routine content from the 22 Nov ~20:15 UTC Senate lists; every linked document is Rpublic = 1 (checked one by one):
#  Education main 46 (18 Nov) summary + 2nd notice; 47 (Wed 25 Nov, 10.30, CA 426, OECD readiness) new date card;
#            45 (11 Nov) approved minutes link (docs only).
#  Education learning 23 (18 Nov) summary; vocational 34 (18 Nov) summary; vocational 35 (Wed 25 Nov, 13.30, CA 328) new
#            date card; higher 40 (17 Nov) summary + 2nd notice; higher 41 (23 Nov) 2nd notice link (docs only).
#  Environment main 41 (17 Nov) summary (complaint written as allegation, no private names); 42 (Tue 24 Nov, 14.00, CA 429)
#            new date card; 40 (10 Nov) approved minutes link (docs only). Climate 4 (19 Nov) summary.
#  Energy main 52 (Tue 24 Nov, 15.00-17.00, CA 427) new date card; 23 (8 Apr): presiding person corrected to the Third
#            Vice-Chair นายสัมพันธ์ ชัยวิเศษจินดา (approved minutes ref 10010191 p.2; asked by the weekly accuracy check).
#  Not used (Rpublic = 2, not public): all sign-in sheets, fee reports, invitation letters, agendas of higher 40 / vocational 34 /
#  learning 23, minutes of higher 39 / vocational 33 / learning 22, and every Energy waste 6-9 document.
#  Share cards, calendar files (past ones removed), 43 English lines (add only), SUBS tab lines for Education + Environment.
# NEEDS 142 + 143 + 144 FIRST (made on top of them; SUBS line hashes taken after 144). Home cards, m/ pages and search index are
# refreshed by run_bundle.sh. Idempotent; no git, no network. Needs $HUB.
set -euo pipefail
: "${HUB:?HUB not set}"
SRC=$(mktemp -d); trap 'rm -rf "$SRC"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d > "$SRC/p.tgz"
echo "167b906b5e16d181cc56db2bc29368e8ea3d180780b4afb5eb82ce5b35757d17  $SRC/p.tgz" | sha256sum -c --quiet - || { echo "145: embedded payload damaged (file cut short?)" >&2; exit 1; }
tar -xzf "$SRC/p.tgz" -C "$SRC" && rm "$SRC/p.tgz"
test -f "$SRC/payload.json" || { echo "145: payload missing" >&2; exit 1; }
for p in education/2569/index.html education/2569/sub-learning.html education/2569/sub-vocational.html education/2569/sub-higher.html \
         environment/2569/index.html environment/2569/sub-climate.html energy/2569/index.html; do
  test -f "$HUB/$p" || { echo "145: $HUB/$p missing (needs 98_edu_env_energy)" >&2; exit 1; }
done
python3 - "$HUB" <<'PY0' || { echo "145: apply 142_edu_env_sub_text_nov, 143_edu_env_sub_text_oct and 144_edu_env_energy_notice_docs first" >&2; exit 1; }
import json, os, sys
H = sys.argv[1]
ld = lambda p: {f"{x['n']}|{x['date']}": x for x in json.load(open(os.path.join(H, p), encoding="utf-8"))}
h, e = ld("education/2569/sub-higher.json"), ld("energy/2569/meetings.json")
ok = h["39|2026-11-11"].get("items") and h["37|2026-10-20"].get("items") and "41|2026-11-23" in h \
     and "ref=11204400" in json.dumps(e["51|2026-11-17"]["docs"])
sys.exit(0 if ok else 1)
PY0
python3 - "$HUB" "$SRC" <<'PY'
import hashlib, json, os, re, shutil, sys
HUB, SRC = sys.argv[1:3]
P = json.load(open(os.path.join(SRC, "payload.json"), encoding="utf-8"))
FIELDS = ("time", "chair", "chair_key", "chair_role", "agenda_only", "headline", "summary", "items", "tags", "places", "pending",
          "room", "map", "docs")
CMP = dict(ensure_ascii=False, separators=(",", ":"))
ser = lambda a: json.dumps(a, **CMP).replace("</", "<\\/")
dflt = lambda v: json.dumps(v, ensure_ascii=False)
key = lambda m: f"{m['n']}|{m['date']}"
changed = []

def put(path, text):
    old = open(path, encoding="utf-8").read()
    if old != text:
        open(path, "w", encoding="utf-8").write(text); changed.append(os.path.relpath(path, HUB))

def merge(m, new):
    for k in FIELDS:
        if k in new: m[k] = new[k]
        else: m.pop(k, None)

def one(lines, prefix, page):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f"{page}: {prefix} line not found once"
    return idx[0]

def jline(lines, i, prefix, page, dumps):
    """parse a `const X=<json>;` line, check it round-trips with `dumps`, return (value, rebuild)"""
    line = lines[i]; body = line[len(prefix):]; tail = body[len(body.rstrip().rstrip(";")):]
    v = json.loads(body[:len(body) - len(tail)])
    assert prefix + dumps(v) + tail == line, f"{page}: {prefix} does not round-trip; not touching it"
    return v, (lambda nv: prefix + dumps(nv) + tail)

def apply_list(arr, spec, which, label):
    """set / add / delete meetings in a meeting list (DATA line or page json); returns the new list"""
    by = {key(m): m for m in arr}
    for k, new in spec["set"].items():
        assert k in by, f"{label}: meeting {k} not on the page"
        merge(by[k], new)
    arr = [m for m in arr if key(m) not in spec["delete"]]
    for k, a in spec["add"].items():
        if any(key(m) == k for m in arr):
            continue
        order = a["order"] if which == "data" else a["json_order"]
        prev = order[:order.index(k)]
        pos = 0
        for i, m in enumerate(arr):
            if key(m) in prev: pos = i + 1
        arr.insert(pos, a["data"] if which == "data" else a["json"])
    return arr

for page, spec in P["pages"].items():
    for k, a in spec["add"].items():
        a["order"] = spec["order"]
    p = os.path.join(HUB, page); lines = open(p, encoding="utf-8").read().split("\n")
    i = one(lines, "const DATA=", page); arr, mk = jline(lines, i, "const DATA=", page, ser)
    lines[i] = mk(apply_list(arr, spec, "data", page))
    if spec["tl"]:     # timeline: replace (or drop) the events of these meetings
        i = one(lines, "const TL=", page); tl, mk = jline(lines, i, "const TL=", page, dflt)
        for n, ev in spec["tl"].items():
            tl = [e for e in tl if str(e[6]) != n] + ev
        lines[i] = mk(sorted(tl, key=lambda e: e[0]))
    if spec["cal"]:    # calendar links of these meetings (None = meeting removed)
        i = one(lines, "const EZ=", page); ez, mk = jline(lines, i, "const EZ=", page, dflt)
        for n, cal in spec["cal"].items():
            if cal is None: ez["cal"].pop(n, None)
            else: ez["cal"][n] = cal
        ez["cal"] = dict(sorted(ez["cal"].items(), key=lambda kv: -int(kv[0]))) if all(x.isdigit() for x in ez["cal"]) else ez["cal"]
        lines[i] = mk(ez)
    if spec["sharev"]:  # share-card hashes (None = meeting removed); SHARE_V is kept newest first
        i = one(lines, "const SHARE_P=", page); l = lines[i]
        mt = re.search(r"SHARE_V=(\{.*?\}),SHARE_QR=", l); sv = json.loads(mt.group(1))
        assert dflt(sv) == mt.group(1), f"{page}: SHARE_V does not round-trip"
        for n, h in spec["sharev"].items():
            if h is None: sv.pop(n, None)
            else: sv[n] = h
        sv = dict(sorted(sv.items(), key=lambda kv: -int(kv[0])))
        lines[i] = l[:mt.start(1)] + dflt(sv) + l[mt.end(1):]
    i = one(lines, "const UPDATED=", page)
    if lines[i] < spec["updated"]:
        lines[i] = spec["updated"]
    put(p, "\n".join(lines))
    # the page's meeting list json (indent=1, no final newline, as csite writes it)
    jp = os.path.join(os.path.dirname(p), spec["json"]); raw = open(jp, encoding="utf-8").read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f"{spec['json']} does not round-trip; not touching it"
    put(jp, json.dumps(apply_list(ms, spec, "json", jp), ensure_ascii=False, indent=1))

# main pages: subcommittee tab data, whole line from the fresh build; refuse if live changed since the payload was made
for page, (base, line) in P["subs"].items():
    p = os.path.join(HUB, page); lines = open(p, encoding="utf-8").read().split("\n")
    i = one(lines, "const SUBS=", page)
    if lines[i] != line:
        assert hashlib.sha256(lines[i].encode()).hexdigest() == base, f"{page}: SUBS line changed since item 144; not touching it"
        lines[i] = line
    i = one(lines, "const UPDATED=", page)
    if lines[i] < 'const UPDATED="2026-11-22";':
        lines[i] = 'const UPDATED="2026-11-22";'
    put(p, "\n".join(lines))

for rel in P["files"]:
    s, d = os.path.join(SRC, rel), os.path.join(HUB, rel)
    os.makedirs(os.path.dirname(d), exist_ok=True)
    if not (os.path.exists(d) and open(s, "rb").read() == open(d, "rb").read()):
        shutil.copyfile(s, d); changed.append(rel)
for rel in P["delete"]:
    d = os.path.join(HUB, rel)
    if os.path.exists(d):
        os.remove(d); changed.append("-" + rel)

for rel, add in P["i18n"].items():
    p = os.path.join(HUB, rel); raw = open(p, encoding="utf-8").read(); d = json.loads(raw)
    assert json.dumps(d, **CMP) == raw, f"{rel} format changed; not touching it"
    for k, v in add.items():
        d.setdefault(k, v)
    put(p, json.dumps(d, **CMP))
print("145_edu_env_energy_nov22: changed", len(changed), "files:", ", ".join(changed[:14]) + (" ..." if len(changed) > 14 else "") if changed else "none (already applied)")

# self-check
for page, spec in P["pages"].items():
    p = os.path.join(HUB, page); d = os.path.dirname(p); t = open(p, encoding="utf-8").read().replace("<\\/", "</")
    data = {key(m): m for m in json.loads([l for l in t.split("\n") if l.startswith("const DATA=")][0][len("const DATA="):].rstrip(";"))}
    ms = {key(m): m for m in json.load(open(os.path.join(d, spec["json"]), encoding="utf-8"))}
    for k, new in spec["set"].items():
        for src in (data, ms):
            assert all(src[k].get(f) == new.get(f) for f in FIELDS), f"{page}: {k} not updated"
    for k, a in spec["add"].items():
        assert k in data and k in ms and data[k]["headline"] == a["data"]["headline"], f"{page}: {k} not added"
    for k in spec["delete"]:
        assert k not in data and k not in ms, f"{page}: {k} still there"
    for n, h in spec["sharev"].items():
        sp = os.path.join(d, "s", f"{spec['prefix']}{n}.html")
        if h:
            assert f"img/s/{spec['prefix']}{n}-{h}.jpg" in open(sp, encoding="utf-8").read(), f"{sp}: new card not linked"
            assert os.path.getsize(os.path.join(d, "img", "s", f"{spec['prefix']}{n}-{h}.jpg")) > 5000, f"{n}: card missing"
            assert f'"{n}": "{h}"' in t, f"{page}: SHARE_V {n}"
        else:
            assert not os.path.exists(sp) and f'"{n}": "' not in re.search(r"SHARE_V=\{.*?\}", t).group(0), f"{page}: {n} share left"
    for n, ev in spec["tl"].items():
        tl = json.loads([l for l in t.split("\n") if l.startswith("const TL=")][0][len("const TL="):].rstrip(";"))
        assert [e for e in tl if str(e[6]) == n] == ev, f"{page}: TL {n}"
H = HUB
ld = lambda p: {key(x): x for x in json.load(open(os.path.join(H, p), encoding="utf-8"))}
def has(p, k, *refs, **kv):
    m = ld(p)[k]; d = json.dumps(m.get("docs"))
    assert all(f"ref={r}" in d for r in refs), f"{p} {k}: docs {refs}"
    for f, v in kv.items():
        assert v in str(m.get(f)), f"{p} {k}: {f} {m.get(f)!r}"
    return m
has("education/2569/meetings.json", "46|2026-11-18", "11216756", "11216745", headline="รายงาน")
assert has("education/2569/meetings.json", "47|2026-11-25", "11216302", time="10.30", room="CA 426")["upcoming"]
has("education/2569/meetings.json", "45|2026-11-11", "11216449")
has("education/2569/sub-learning.json", "23|2026-11-18", "11216597", chair="วิวัฒน์")
has("education/2569/sub-vocational.json", "34|2026-11-18", "11216662", chair="สุทิน")
assert has("education/2569/sub-vocational.json", "35|2026-11-25", "11217794", time="13.30", room="CA 328")["upcoming"]
has("education/2569/sub-higher.json", "40|2026-11-17", "11216622", "11216617", chair="อมรศักดิ์")
has("education/2569/sub-higher.json", "41|2026-11-23", "11205183", "11216527", time="10.30")
has("environment/2569/meetings.json", "40|2026-11-10", "11227206")
has("environment/2569/meetings.json", "41|2026-11-17", "11226642", time="14.30", room="CA 429")
assert has("environment/2569/meetings.json", "42|2026-11-24", "11227765", time="14.00", room="CA 429")["upcoming"]
has("environment/2569/sub-climate.json", "4|2026-11-19", "11227922", time="13.30")
m23 = ld("energy/2569/meetings.json")["23|2026-04-08"]
assert m23["chair"] == "นายสัมพันธ์ ชัยวิเศษจินดา" and m23["chair_role"].startswith("รองประธานคณะกรรมาธิการ คนที่สาม"), "energy 23 presiding"
assert has("energy/2569/meetings.json", "52|2026-11-24", "11216654", time="15.00", room="CA 427")["upcoming"]
NOTPUB = ("11216748", "11216631", "11216660", "11216620", "11216584", "11216633", "11216607", "11216602", "11216667", "11216626",
          "11216034", "11174786", "11216109", "11216106", "11216107", "11216097", "11216304", "11216305", "11216307")
for page in list(P["pages"]) + [s["json"] and os.path.join(os.path.dirname(p), s["json"]) for p, s in P["pages"].items()]:
    t = open(os.path.join(H, page), encoding="utf-8").read()
    assert not [r for r in NOTPUB if f"ref={r}" in t], f"{page}: a non-public document is linked"
for page, (base, line) in P["subs"].items():
    assert line in open(os.path.join(HUB, page), encoding="utf-8").read().split("\n"), f"{page}: SUBS"
print("145_edu_env_energy_nov22 OK")
PY
exit 0
